3	import (
4		"math"
5		"net/http"
6		"sort"
7		"sync"
8	)
9	
10	// deviceInput is one member of a create-pool request.
11	type deviceInput struct {
12		ID            string `json:"id"`
13		CapacityBytes int64  `json:"capacityBytes"`
14		FaultDomain   string `json:"faultDomain"`
15	}
16	
17	type createPoolInput struct {
18		ID      string        `json:"id"`
19		Devices []deviceInput `json:"devices"`
20	}
21	
22	type reservationInput struct {
23		RequestID string `json:"requestId"`
24		Bytes     int64  `json:"bytes"`
25	}
26	
27	// deviceView is the public representation of a pool device.
28	type deviceView struct {
29		ID            string `json:"id"`
30		CapacityBytes int64  `json:"capacityBytes"`
31		FaultDomain   string `json:"faultDomain"`
32	}
33	
34	// poolView is the public representation of a storage pool.
35	type poolView struct {
36		ID               string       `json:"id"`
37		Devices          []deviceView `json:"devices"`
38		RawCapacityBytes int64        `json:"rawCapacityBytes"`
39		AllocatedBytes   int64        `json:"allocatedBytes"`
40		AvailableBytes   int64        `json:"availableBytes"`
41	}
42	
43	// reservationView is the result of a successful reservation request.
44	type reservationView struct {
45		PoolID    string `json:"poolId"`
46		RequestID string `json:"requestId"`
47		Bytes     int64  `json:"bytes"`
48	}
49	
50	type reservation struct {
51		requestID string
52		bytes     int64
53		tenant    string
54	}
55	
56	// pool is one storage pool. tenantUsed tracks each tenant's charged bytes
57	// (reservations + volumes + snapshots + objects) inside the pool; quotas maps
58	// a tenant id to its byte limit. Tenants without a quota entry are unlimited.
59	type pool struct {
60		id            string
61		devices       []deviceInput
62		rawCapacity   int64
63		reservations  map[string]reservation
64		volumeBytes   int64 // total sizeBytes of volumes in this pool
65		snapshotBytes int64 // total sizeBytes of snapshots held in this pool
66		objectBytes   int64 // total sizeBytes of objects in buckets of this pool
67		tenantUsed    map[string]int64
68		quotas        map[string]int64
69	}
70	
71	// volume is a capacity allocation inside a pool with an optional exclusive
72	// node binding. generation is bumped on every binding state change, every
73	// resize and every restore. cloneSource records the snapshot a volume was
74	// cloned from ("" for a volume created directly) so clone retries can be told
75	// apart from foreign ids. createdSizeBytes records the size from the original
76	// creation request (the snapshot size for clones); idempotent create replays
77	// match it rather than the live sizeBytes, so resizing a volume never turns a
78	// faithful retry into a volume_exists conflict. tenant is the owning tenant;
79	// its current sizeBytes is charged to the tenant's usage in the pool.
80	// instanceID distinguishes successive volumes that reuse the same id: it is
81	// assigned from the store-wide sequence at creation, so a snapshot taken from
82	// a deleted volume never matches a later volume recreated under the same id.
83	type volume struct {
84		id               string
85		poolID           string
86		sizeBytes        int64
87		createdSizeBytes int64
88		generation       int64
89		binding          string // "" when unbound
90		cloneSource      string // snapshot id when produced via a clone
91		tenant           string
92		instanceID       int64
93	}
94	
95	func (p *pool) allocated() int64 {
96		var total int64 = p.volumeBytes + p.snapshotBytes + p.objectBytes
97		for _, r := range p.reservations {
98			total += r.bytes
99		}
100		return total
101	}
102	
103	func (p *pool) view() poolView {
104		devices := make([]deviceView, len(p.devices))
105		for i, d := range p.devices {
106			devices[i] = deviceView{ID: d.ID, CapacityBytes: d.CapacityBytes, FaultDomain: d.FaultDomain}
107		}
108		allocated := p.allocated()
109		return poolView{
110			ID:               p.id,
111			Devices:          devices,
112			RawCapacityBytes: p.rawCapacity,
113			AllocatedBytes:   allocated,
114			AvailableBytes:   p.rawCapacity - allocated,
115		}
116	}
117	
118	// store is the in-memory state of the service. It is wiped on restart.
119	type store struct {
120		mu          sync.RWMutex
121		pools       map[string]*pool
122		volumes     map[string]*volume
123		snapshots   map[string]*snapshot
124		buckets     map[string]*bucket
125		deviceOwner map[string]string
126		// auditEvents is the append-only audit log; auditSeq is the sequence of
127		// its last entry (0 while empty). Both are mutated under mu, together with
128		// the business state each event describes.
129		auditEvents []auditEvent
130		auditSeq    int64
131		// volumeInstanceSeq is the sequence of the last assigned volume instance
132		// id (0 while none). It is incremented under mu at every volume creation,
133		// so a recreated volume never shares an instance id with its predecessor.
134		volumeInstanceSeq int64
135	}
136	
137	func newStore() *store {
138		return &store{
139			pools:       make(map[string]*pool),
140			volumes:     make(map[string]*volume),
141			snapshots:   make(map[string]*snapshot),
142			buckets:     make(map[string]*bucket),
143			deviceOwner: make(map[string]string),
144		}
145	}
146	
147	func validID(id string) bool {
148		return idPattern.MatchString(id)
149	}
150	
151	func (s *store) listPools(w http.ResponseWriter) {
152		s.mu.RLock()
153		ids := make([]string, 0, len(s.pools))
154		for id := range s.pools {
155			ids = append(ids, id)
156		}
157		sort.Strings(ids)
158		items := make([]poolView, 0, len(ids))
159		for _, id := range ids {
160			items = append(items, s.pools[id].view())
161		}
162		s.mu.RUnlock()
163		writeJSON(w, http.StatusOK, map[string]any{"items": items})
164	}
165	
166	func (s *store) getPool(w http.ResponseWriter, id string) {
167		if !validID(id) {
168			writeError(w, http.StatusBadRequest, "invalid_request")
169			return
170		}
171		s.mu.RLock()
172		p, ok := s.pools[id]
173		var v poolView
174		if ok {
175			v = p.view()
176		}
177		s.mu.RUnlock()
178		if !ok {
179			writeError(w, http.StatusNotFound, "pool_not_found")
180			return
181		}
182		writeJSON(w, http.StatusOK, v)
183	}
184	
185	func (s *store) createPool(w http.ResponseWriter, r *http.Request) {
186		var in createPoolInput
187		if !decodeRequest(r, &in) {
188			writeError(w, http.StatusBadRequest, "invalid_request")
189			return
190		}
191		// Validate the whole payload before touching any state so a failure
192		// never leaves a partial pool behind.
193		if !validID(in.ID) || len(in.Devices) == 0 {
194			writeError(w, http.StatusBadRequest, "invalid_request")
195			return
196		}
197		seen := make(map[string]bool, len(in.Devices))
198		var rawCapacity int64
199		for _, d := range in.Devices {
200			if !validID(d.ID) || d.CapacityBytes <= 0 || d.FaultDomain == "" || seen[d.ID] {
201				writeError(w, http.StatusBadRequest, "invalid_request")
202				return
203			}
204			if rawCapacity > math.MaxInt64-d.CapacityBytes {
205				writeError(w, http.StatusBadRequest, "invalid_request")
206				return
207			}
208			seen[d.ID] = true
209			rawCapacity += d.CapacityBytes
210		}
211	
212		s.mu.Lock()
213		defer s.mu.Unlock()
214		if _, ok := s.pools[in.ID]; ok {
215			writeError(w, http.StatusConflict, "pool_exists")
216			return
217		}
218		for _, d := range in.Devices {
219			if _, busy := s.deviceOwner[d.ID]; busy {
220				writeError(w, http.StatusConflict, "device_in_use")
221				return
222			}
223		}
224	
225		devices := append([]deviceInput(nil), in.Devices...)
226		p := &pool{
227			id:           in.ID,
228			devices:      devices,
229			rawCapacity:  rawCapacity,
230			reservations: make(map[string]reservation),
231			tenantUsed:   make(map[string]int64),
232			quotas:       make(map[string]int64),
233		}
234		s.pools[in.ID] = p
235		for _, d := range devices {
236			s.deviceOwner[d.ID] = in.ID
237		}
238		s.appendAudit(auditPoolCreated, storagePoolPath+"/"+in.ID, in.ID, 0)
239		writeJSON(w, http.StatusCreated, p.view())
240	}
241	
242	func (s *store) deletePool(w http.ResponseWriter, id string) {
243		if !validID(id) {
244			writeError(w, http.StatusBadRequest, "invalid_request")
245			return
246		}
247		s.mu.Lock()
248		defer s.mu.Unlock()
249		p, ok := s.pools[id]
250		if !ok {
251			writeError(w, http.StatusNotFound, "pool_not_found")
252			return
253		}
254		if len(p.reservations) > 0 || p.volumeBytes > 0 || p.snapshotBytes > 0 || p.objectBytes > 0 {
255			writeError(w, http.StatusConflict, "pool_not_empty")
256			return
257		}
258		// An empty bucket still blocks pool deletion even though it charges no
259		// bytes.
260		for _, b := range s.buckets {
261			if b.poolID == id {
262				writeError(w, http.StatusConflict, "pool_not_empty")
263				return
264			}
265		}
266		for _, d := range p.devices {
267			delete(s.deviceOwner, d.ID)
268		}
269		delete(s.pools, id)
270		s.appendAudit(auditPoolDeleted, storagePoolPath+"/"+id, id, 0)
271		w.WriteHeader(http.StatusNoContent)
272	}
273	
274	func (s *store) createReservation(w http.ResponseWriter, r *http.Request, poolID string) {
275		var in reservationInput
276		if !decodeRequest(r, &in) {
277			writeError(w, http.StatusBadRequest, "invalid_request")
278			return
279		}
280		tenant, tok := extractTenant(r.Header)
281		if !tok || !validID(poolID) || !validID(in.RequestID) || in.Bytes <= 0 {
282			writeError(w, http.StatusBadRequest, "invalid_request")
283			return
284		}
285	
286		s.mu.Lock()
287		defer s.mu.Unlock()
288		p, ok := s.pools[poolID]
289		if !ok {
290			writeError(w, http.StatusNotFound, "pool_not_found")
291			return
292		}
293		if existing, dup := p.reservations[in.RequestID]; dup {
294			if existing.bytes != in.Bytes || existing.tenant != tenant {
295				writeError(w, http.StatusConflict, "idempotency_conflict")
296				return
297			}
298			writeJSON(w, http.StatusOK, reservationView{PoolID: poolID, RequestID: existing.requestID, Bytes: existing.bytes})
299			return
300		}
301		// Holding the store lock makes the quota and capacity checks plus the
302		// charge atomic, so concurrent creates can never exceed either limit.
303		if p.tenantQuotaExceeded(tenant, in.Bytes) {
304			writeError(w, http.StatusConflict, "tenant_quota_exceeded")
305			return
306		}
307		allocated := p.allocated()
308		if allocated > p.rawCapacity-in.Bytes {
309			writeError(w, http.StatusConflict, "insufficient_capacity")
310			return
311		}
312		p.reservations[in.RequestID] = reservation{requestID: in.RequestID, bytes: in.Bytes, tenant: tenant}
313		p.tenantUsed[tenant] += in.Bytes
314		s.appendAudit(auditReservationCreated,
315			storagePoolPath+"/"+poolID+"/reservations/"+in.RequestID, poolID, in.Bytes)
316		writeJSON(w, http.StatusCreated, reservationView{PoolID: poolID, RequestID: in.RequestID, Bytes: in.Bytes})
317	}
318	
319	func (s *store) deleteReservation(w http.ResponseWriter, poolID, requestID string) {
320		if !validID(poolID) || !validID(requestID) {
321			writeError(w, http.StatusBadRequest, "invalid_request")
322			return
323		}
324		s.mu.Lock()
325		defer s.mu.Unlock()
326		p, ok := s.pools[poolID]
327		if !ok {
328			writeError(w, http.StatusNotFound, "pool_not_found")
329			return
330		}
331		// Deleting an unknown or already-deleted reservation is a success with
332		// no state change, so only a real deletion records an event.
333		if r, existed := p.reservations[requestID]; existed {
334			delete(p.reservations, requestID)
335			p.tenantUsed[r.tenant] -= r.bytes
336			s.appendAudit(auditReservationDeleted,
337				storagePoolPath+"/"+poolID+"/reservations/"+requestID, poolID, -r.bytes)
338		}
339		w.WriteHeader(http.StatusNoContent)
340	}
