1	package server
2	
3	import (
4		"crypto/rand"
5		"crypto/sha256"
6		"encoding/hex"
7		"io"
8		"net/http"
9		"net/url"
10		"sort"
11		"strconv"
12		"strings"
13		"unicode"
14		"unicode/utf8"
15	)
16	
17	// metaPrefix is the header prefix carrying user metadata on object writes.
18	// The constant is already in Go's canonical header form.
19	const metaPrefix = "X-Vaultgrid-Meta-"
20	
21	// versionHeader carries the versionId of a stored object version on write
22	// responses and on versioned reads. It is already in Go's canonical form.
23	const versionHeader = "X-Vaultgrid-Version-Id"
24	
25	type createBucketInput struct {
26		ID     string `json:"id"`
27		PoolID string `json:"poolId"`
28	}
29	
30	// versioningInput is the sole accepted body of PUT .../versioning: the only
31	// valid payload is {"enabled":true}.
32	type versioningInput struct {
33		Enabled bool `json:"enabled"`
34	}
35	
36	// bucketView is the public representation of a bucket.
37	type bucketView struct {
38		ID          string `json:"id"`
39		PoolID      string `json:"poolId"`
40		ObjectCount int    `json:"objectCount"`
41		BytesUsed   int64  `json:"bytesUsed"`
42	}
43	
44	// versioningView is the public representation of a bucket's versioning state.
45	type versioningView struct {
46		Enabled bool `json:"enabled"`
47	}
48	
49	// objectView is the public representation of an object after a write, and
50	// the summary shape used in object listings.
51	type objectView struct {
52		Key       string            `json:"key"`
53		SizeBytes int64             `json:"sizeBytes"`
54		Metadata  map[string]string `json:"metadata"`
55		Etag      string            `json:"etag"`
56	}
57	
58	// versionedObjectView is the write response shape in a versioned bucket.
59	type versionedObjectView struct {
60		Key       string            `json:"key"`
61		VersionID string            `json:"versionId"`
62		SizeBytes int64             `json:"sizeBytes"`
63		Metadata  map[string]string `json:"metadata"`
64		Etag      string            `json:"etag"`
65	}
66	
67	// objectVersionView is one row of GET .../object-versions.
68	type objectVersionView struct {
69		Key          string            `json:"key"`
70		VersionID    string            `json:"versionId"`
71		IsLatest     bool              `json:"isLatest"`
72		DeleteMarker bool              `json:"deleteMarker"`
73		SizeBytes    int64             `json:"sizeBytes"`
74		Etag         string            `json:"etag"`
75		Metadata     map[string]string `json:"metadata"`
76	}
77	
78	// bucket is a namespace of objects bound to one pool. tenant owns the bucket;
79	// object bytes are charged to the tenant's usage in the pool.
80	//
81	// Each key maps to one object whose versions are kept in creation order
82	// (oldest first, newest last). In a non-versioned bucket the slice holds at
83	// most one data version and every write replaces it; in a versioned bucket
84	// writes append data versions and unversioned deletes append delete markers.
85	// bytesUsed counts every data version, including hidden ones; objectCount
86	// counts only keys whose latest version is a data version.
87	type bucket struct {
88		id                string
89		poolID            string
90		tenant            string
91		versioningEnabled bool
92		objects           map[string]*object
93	}
94	
95	func (b *bucket) bytesUsed() int64 {
96		var total int64
97		for _, o := range b.objects {
98			for _, v := range o.versions {
99				if !v.isMarker {
100					total += v.sizeBytes
101				}
102			}
103		}
104		return total
105	}
106	
107	func (b *bucket) visibleCount() int {
108		count := 0
109		for _, o := range b.objects {
110			if o.visible() != nil {
111				count++
112			}
113		}
114		return count
115	}
116	
117	func (b *bucket) view() bucketView {
118		return bucketView{ID: b.id, PoolID: b.poolID, ObjectCount: b.visibleCount(), BytesUsed: b.bytesUsed()}
119	}
120	
121	// notEmpty reports whether any data version or delete marker remains; such a
122	// bucket cannot be deleted.
123	func (b *bucket) notEmpty() bool { return len(b.objects) > 0 }
124	
125	// findVersion returns the version with the given id and its position, or nil
126	// when the key or version does not exist.
127	func (b *bucket) findVersion(key, versionID string) (*objectVersion, int) {
128		o := b.objects[key]
129		if o == nil {
130			return nil, -1
131		}
132		for i, v := range o.versions {
133			if v.versionID == versionID {
134				return v, i
135			}
136		}
137		return nil, -1
138	}
139	
140	// newVersionID mints a unique, non-empty version id. The caller must hold the
141	// store write lock.
142	func (b *bucket) newVersionID() string {
143		for {
144			var raw [16]byte
145			if _, err := rand.Read(raw[:]); err != nil {
146				// crypto/rand failure is not recoverable; a panic keeps a failed
147				// write from ever committing a placeholder id.
148				panic(err)
149			}
150			id := hex.EncodeToString(raw[:])
151			collision := false
152			for _, o := range b.objects {
153				for _, v := range o.versions {
154					if v.versionID == id {
155						collision = true
156					}
157				}
158			}
159			if !collision {
160				return id
161			}
162		}
163	}
164	
165	// object groups every version of one key.
166	type object struct {
167		key      string
168		versions []*objectVersion
169	}
170	
171	// latest returns the most recently created version, or nil when the key has
172	// no versions at all.
173	func (o *object) latest() *objectVersion {
174		if o == nil || len(o.versions) == 0 {
175			return nil
176		}
177		return o.versions[len(o.versions)-1]
178	}
179	
180	// visible returns the current data version clients see without a versionId:
181	// the latest version unless that is a delete marker.
182	func (o *object) visible() *objectVersion {
183		v := o.latest()
184		if v == nil || v.isMarker {
185			return nil
186		}
187		return v
188	}
189	
190	// objectVersion is one stored data version or a delete marker. A marker
191	// carries no content, etag or metadata and charges no bytes. etag on a data
192	// version is the quoted lowercase hex SHA-256 of content.
193	type objectVersion struct {
194		versionID string
195		content   []byte
196		metadata  map[string]string
197		etag      string
198		sizeBytes int64
199		isMarker  bool
200	}
201	
202	func (v *objectVersion) objectView(key string) objectView {
203		return objectView{Key: key, SizeBytes: v.sizeBytes, Metadata: v.metadata, Etag: v.etag}
204	}
205	
206	func (v *objectVersion) versionedView(key string) versionedObjectView {
207		return versionedObjectView{Key: key, VersionID: v.versionID, SizeBytes: v.sizeBytes, Metadata: v.metadata, Etag: v.etag}
208	}
209	
210	// routeBuckets dispatches /v1/buckets and its sub-paths. The object key is
211	// the remainder of the path after "objects/" (already URL-decoded once by
212	// the net/http layer) and may contain slashes, so it is not split here.
213	func (s *store) routeBuckets(w http.ResponseWriter, r *http.Request) {
214		rest := strings.TrimPrefix(r.URL.Path, bucketPath)
215		if rest == "" {
216			switch r.Method {
217			case http.MethodGet:
218				s.listBuckets(w)
219			case http.MethodPost:
220				s.createBucket(w, r)
221			default:
222				methodNotAllowed(w, http.MethodGet, http.MethodPost)
223			}
224			return
225		}
226		// rest begins with "/"; the bucket id is the single next segment.
227		bucketID, tail, found := strings.Cut(rest[1:], "/")
228		if bucketID == "" {
229			writeError(w, http.StatusNotFound, "not_found")
230			return
231		}
232		if !found {
233			switch r.Method {
234			case http.MethodGet:
235				s.getBucket(w, bucketID)
236			case http.MethodDelete:
237				s.deleteBucket(w, bucketID)
238			default:
239				methodNotAllowed(w, http.MethodGet, http.MethodDelete)
240			}
241			return
242		}
243		switch tail {
244		case "objects":
245			if r.Method != http.MethodGet {
246				methodNotAllowed(w, http.MethodGet)
247				return
248			}
249			s.listObjects(w, r, bucketID)
250			return
251		case "versioning":
252			switch r.Method {
253			case http.MethodGet:
254				s.getVersioning(w, r, bucketID)
255			case http.MethodPut:
256				s.putVersioning(w, r, bucketID)
257			default:
258				methodNotAllowed(w, http.MethodGet, http.MethodPut)
259			}
260			return
261		case "object-versions":
262			if r.Method != http.MethodGet {
263				methodNotAllowed(w, http.MethodGet)
264				return
265			}
266			s.listObjectVersions(w, r, bucketID)
267			return
268		}
269		if key, ok := strings.CutPrefix(tail, "objects/"); ok {
270			switch r.Method {
271			case http.MethodPut:
272				s.putObject(w, r, bucketID, key)
273			case http.MethodGet:
274				s.getObject(w, r, bucketID, key, false)
275			case http.MethodHead:
276				s.getObject(w, r, bucketID, key, true)
277			case http.MethodDelete:
278				s.deleteObject(w, r, bucketID, key)
279			default:
280				methodNotAllowed(w, http.MethodPut, http.MethodGet, http.MethodHead, http.MethodDelete)
281			}
282			return
283		}
284		writeError(w, http.StatusNotFound, "not_found")
285	}
286	
287	func (s *store) listBuckets(w http.ResponseWriter) {
288		s.mu.RLock()
289		ids := make([]string, 0, len(s.buckets))
290		for id := range s.buckets {
291			ids = append(ids, id)
292		}
293		sort.Strings(ids)
294		items := make([]bucketView, 0, len(ids))
295		for _, id := range ids {
296			items = append(items, s.buckets[id].view())
297		}
298		s.mu.RUnlock()
299		writeJSON(w, http.StatusOK, map[string]any{"items": items})
300	}
301	
302	func (s *store) getBucket(w http.ResponseWriter, id string) {
303		if !validID(id) {
304			writeError(w, http.StatusBadRequest, "invalid_request")
305			return
306		}
307		s.mu.RLock()
308		b, ok := s.buckets[id]
309		var v bucketView
310		if ok {
311			v = b.view()
312		}
313		s.mu.RUnlock()
314		if !ok {
315			writeError(w, http.StatusNotFound, "bucket_not_found")
316			return
317		}
318		writeJSON(w, http.StatusOK, v)
319	}
320	
321	func (s *store) createBucket(w http.ResponseWriter, r *http.Request) {
322		var in createBucketInput
323		if !decodeRequest(r, &in) {
324			writeError(w, http.StatusBadRequest, "invalid_request")
325			return
326		}
327		tenant, tok := extractTenant(r.Header)
328		if !tok || !validID(in.ID) || !validID(in.PoolID) {
329			writeError(w, http.StatusBadRequest, "invalid_request")
330			return
331		}
332	
333		s.mu.Lock()
334		defer s.mu.Unlock()
335		if existing, dup := s.buckets[in.ID]; dup {
336			if existing.poolID == in.PoolID && existing.tenant == tenant {
337				writeJSON(w, http.StatusOK, existing.view())
338				return
339			}
340			writeError(w, http.StatusConflict, "bucket_exists")
341			return
342		}
343		if _, ok := s.pools[in.PoolID]; !ok {
344			writeError(w, http.StatusNotFound, "pool_not_found")
345			return
346		}
347		s.buckets[in.ID] = &bucket{id: in.ID, poolID: in.PoolID, tenant: tenant, objects: make(map[string]*object)}
348		s.appendAudit(auditBucketCreated, bucketPath+"/"+in.ID, in.PoolID, 0)
349		writeJSON(w, http.StatusCreated, s.buckets[in.ID].view())
350	}
351	
352	func (s *store) deleteBucket(w http.ResponseWriter, id string) {
353		if !validID(id) {
354			writeError(w, http.StatusBadRequest, "invalid_request")
355			return
356		}
357		s.mu.Lock()
358		defer s.mu.Unlock()
359		b, ok := s.buckets[id]
360		if !ok {
361			writeError(w, http.StatusNotFound, "bucket_not_found")
362			return
363		}
364		// A bucket with any surviving data version or delete marker is not empty.
365		if b.notEmpty() {
366			writeError(w, http.StatusConflict, "bucket_not_empty")
367			return
368		}
369		delete(s.buckets, id)
370		s.appendAudit(auditBucketDeleted, bucketPath+"/"+id, b.poolID, 0)
371		w.WriteHeader(http.StatusNoContent)
372	}
373	
374	// getVersioning handles GET /v1/buckets/{bucketId}/versioning.
375	func (s *store) getVersioning(w http.ResponseWriter, r *http.Request, bucketID string) {
376		if !validID(bucketID) || r.URL.RawQuery != "" {
377			writeError(w, http.StatusBadRequest, "invalid_request")
378			return
379		}
380		s.mu.RLock()
381		b, ok := s.buckets[bucketID]
382		enabled := ok && b.versioningEnabled
383		s.mu.RUnlock()
384		if !ok {
385			writeError(w, http.StatusNotFound, "bucket_not_found")
386			return
387		}
388		writeJSON(w, http.StatusOK, versioningView{Enabled: enabled})
389	}
390	
391	// putVersioning handles PUT /v1/buckets/{bucketId}/versioning. Enabling is
392	// idempotent: first enablement migrates existing objects to versions and is
393	// audited; replays answer 200 with no state change and no event. The only
394	// accepted body is {"enabled":true}.
395	func (s *store) putVersioning(w http.ResponseWriter, r *http.Request, bucketID string) {
396		var in versioningInput
397		if !decodeRequest(r, &in) || !in.Enabled {
398			writeError(w, http.StatusBadRequest, "invalid_request")
399			return
400		}
401		if !validID(bucketID) || r.URL.RawQuery != "" {
402			writeError(w, http.StatusBadRequest, "invalid_request")
403			return
404		}
405	
406		s.mu.Lock()
407		defer s.mu.Unlock()
408		b, ok := s.buckets[bucketID]
409		if !ok {
410			writeError(w, http.StatusNotFound, "bucket_not_found")
411			return
412		}
413		if b.versioningEnabled {
414			// Idempotent replay: no state change, so no audit event.
415			writeJSON(w, http.StatusOK, versioningView{Enabled: true})
416			return
417		}
418		b.versioningEnabled = true
419		// Every existing object becomes the first (latest) data version of its
420		// key. Capacity does not change: the bytes were already charged once.
421		keys := make([]string, 0, len(b.objects))
422		for key := range b.objects {
423			keys = append(keys, key)
424		}
425		sort.Strings(keys)
426		for _, key := range keys {
427			for _, v := range b.objects[key].versions {
428				v.versionID = b.newVersionID()
429			}
430		}
431		s.appendAudit(auditBucketVersioning, bucketPath+"/"+bucketID+"/versioning", b.poolID, 0)
432		writeJSON(w, http.StatusOK, versioningView{Enabled: true})
433	}
434	
435	// validObjectKey reports whether key is 1..1024 bytes of valid UTF-8 with no
436	// control characters.
437	func validObjectKey(key string) bool {
438		if len(key) == 0 || len(key) > 1024 || !utf8.ValidString(key) {
439			return false
440		}
441		for _, r := range key {
442			if unicode.IsControl(r) {
443				return false
444			}
445		}
446		return true
447	}
448	
449	// extractMetadata collects the X-Vaultgrid-Meta-* request headers into a
450	// metadata map keyed by the suffix after the prefix. A header with an empty
451	// suffix or a value that is not valid UTF-8 or carries control characters
452	// makes the whole request invalid.
453	func extractMetadata(h http.Header) (map[string]string, bool) {
454		meta := make(map[string]string)
455		for name, values := range h {
456			suffix, ok := strings.CutPrefix(name, metaPrefix)
457			if !ok {
458				continue
459			}
460			if suffix == "" {
461				return nil, false
462			}
463			for _, v := range values {
464				if !utf8.ValidString(v) {
465					return nil, false
466				}
467				for _, r := range v {
468					if unicode.IsControl(r) {
469						return nil, false
470					}
471				}
472			}
473			meta[suffix] = strings.Join(values, ", ")
474		}
475		return meta, true
476	}
477	
478	// parsePrecondition validates the conditional-write headers. It returns the
479	// If-Match etag ("" when absent) and whether If-None-Match: * was given. ok
480	// is false when both headers are present or either has an unsupported form.
481	func parsePrecondition(h http.Header) (ifMatch string, ifNoneMatchStar, ok bool) {
482		matches, hasMatch := h["If-Match"]
483		noneMatches, hasNoneMatch := h["If-None-Match"]
484		if hasMatch && hasNoneMatch {
485			return "", false, false
486		}
487		if hasMatch {
488			if len(matches) != 1 || !isQuotedETag(matches[0]) {
489				return "", false, false
490			}
491			return matches[0], false, true
492		}
493		if hasNoneMatch {
494			if len(noneMatches) != 1 || noneMatches[0] != "*" {
495				return "", false, false
496			}
497			return "", true, true
498		}
499		return "", false, true
500	}
501	
502	// isQuotedETag reports whether v looks like a quoted hex etag, e.g.
503	// "9f86d081...". The content is not checked against any object here.
504	func isQuotedETag(v string) bool {
505		if len(v) < 2 || v[0] != '"' || v[len(v)-1] != '"' {
506			return false
507		}
508		inner := v[1 : len(v)-1]
509		if inner == "" {
510			return false
511		}
512		for _, c := range inner {
513			if !('0' <= c && c <= '9' || 'a' <= c && c <= 'f') {
514				return false
515			}
516		}
517		return true
518	}
519	
520	func etagOf(content []byte) string {
521		sum := sha256.Sum256(content)
522		return `"` + hex.EncodeToString(sum[:]) + `"`
523	}
524	
525	func (s *store) putObject(w http.ResponseWriter, r *http.Request, bucketID, key string) {
526		if !validID(bucketID) || !validObjectKey(key) {
527			writeError(w, http.StatusBadRequest, "invalid_request")
528			return
529		}
530		if r.URL.RawQuery != "" {
531			writeError(w, http.StatusBadRequest, "invalid_request")
532			return
533		}
534		metadata, ok := extractMetadata(r.Header)
535		if !ok {
536			writeError(w, http.StatusBadRequest, "invalid_request")
537			return
538		}
539		ifMatch, ifNoneMatchStar, ok := parsePrecondition(r.Header)
540		if !ok {
541			writeError(w, http.StatusBadRequest, "invalid_request")
542			return
543		}
544		content, err := io.ReadAll(r.Body)
545		if err != nil {
546			writeError(w, http.StatusBadRequest, "invalid_request")
547			return
548		}
549		etag := etagOf(content)
550		size := int64(len(content))
551	
552		s.mu.Lock()
553		defer s.mu.Unlock()
554		b, ok := s.buckets[bucketID]
555		if !ok {
556			writeError(w, http.StatusNotFound, "bucket_not_found")
557			return
558		}
559		p := s.pools[b.poolID]
560		resource := bucketPath + "/" + bucketID + "/objects/" + key
561		obj := b.objects[key]
562	
563		if b.versioningEnabled {
564			s.putObjectVersioned(w, b, p, obj, key, resource, content, metadata, etag, size, ifMatch, ifNoneMatchStar)
565			return
566		}
567	
568		var existing *objectVersion
569		if obj != nil {
570			existing = obj.latest()
571		}
572		// Conditions judge the single current version.
573		if ifMatch != "" && (existing == nil || existing.etag != ifMatch) {
574			writeError(w, http.StatusPreconditionFailed, "precondition_failed")
575			return
576		}
577		if ifNoneMatchStar && existing != nil {
578			writeError(w, http.StatusPreconditionFailed, "precondition_failed")
579			return
580		}
581		var oldSize int64
582		if existing != nil {
583			oldSize = existing.sizeBytes
584		}
585		// The store lock makes the quota and capacity checks plus the charge
586		// atomic, so concurrent writes can never exceed either limit, and a failed
587		// write leaves the old object and its metadata untouched. Objects inherit
588		// the bucket's tenant; only a growing write can breach the quota.
589		if delta := size - oldSize; delta > 0 && p.tenantQuotaExceeded(b.tenant, delta) {
590			writeError(w, http.StatusConflict, "tenant_quota_exceeded")
591			return
592		}
593		if p.allocated() > p.rawCapacity-(size-oldSize) {
594			writeError(w, http.StatusConflict, "insufficient_capacity")
595			return
596		}
597		created := &objectVersion{content: content, metadata: metadata, etag: etag, sizeBytes: size}
598		b.objects[key] = &object{key: key, versions: []*objectVersion{created}}
599		p.objectBytes += size - oldSize
600		p.tenantUsed[b.tenant] += size - oldSize
601		// An overwrite is recorded even when the size delta is zero.
602		status := http.StatusCreated
603		if existing != nil {
604			s.appendAudit(auditObjectOverwritten, resource, b.poolID, size-oldSize)
605			status = http.StatusOK
606		} else {
607			s.appendAudit(auditObjectCreated, resource, b.poolID, size)
608		}
609		w.Header().Set("ETag", etag)
610		writeJSON(w, status, created.objectView(key))
611	}
612	
613	// putObjectVersioned commits a write against a versioned bucket: every
614	// successful put appends a fresh data version charged at its full size,
615	// leaving every older version (and its bytes) in place. Conditional writes
616	// judge only the currently visible version. The caller holds the store lock.
617	func (s *store) putObjectVersioned(w http.ResponseWriter, b *bucket, p *pool, obj *object, key, resource string,
618		content []byte, metadata map[string]string, etag string, size int64, ifMatch string, ifNoneMatchStar bool) {
619		visible := obj.visible()
620		if ifMatch != "" && (visible == nil || visible.etag != ifMatch) {
621			writeError(w, http.StatusPreconditionFailed, "precondition_failed")
622			return
623		}
624		if ifNoneMatchStar && visible != nil {
625			writeError(w, http.StatusPreconditionFailed, "precondition_failed")
626			return
627		}
628		// A new version is charged in full; older versions stay charged.
629		if p.tenantQuotaExceeded(b.tenant, size) {
630			writeError(w, http.StatusConflict, "tenant_quota_exceeded")
631			return
632		}
633		if p.allocated() > p.rawCapacity-size {
634			writeError(w, http.StatusConflict, "insufficient_capacity")
635			return
636		}
637		created := &objectVersion{
638			versionID: b.newVersionID(),
639			content:   content,
640			metadata:  metadata,
641			etag:      etag,
642			sizeBytes: size,
643		}
644		if obj == nil {
645			obj = &object{key: key}
646			b.objects[key] = obj
647		}
648		obj.versions = append(obj.versions, created)
649		p.objectBytes += size
650		p.tenantUsed[b.tenant] += size
651		s.appendAudit(auditObjectVersioned, resource, b.poolID, size)
652		// 201 when the put creates the currently visible object (key was absent or
653		// hidden behind a delete marker), 200 when it overwrites visible data.
654		status := http.StatusCreated
655		if visible != nil {
656			status = http.StatusOK
657		}
658		w.Header().Set("ETag", etag)
659		w.Header().Set(versionHeader, created.versionID)
660		writeJSON(w, status, created.versionedView(key))
661	}
662	
663	// getObject serves both GET and HEAD; headOnly suppresses the body.
664	func (s *store) getObject(w http.ResponseWriter, r *http.Request, bucketID, key string, headOnly bool) {
665		if !validID(bucketID) || !validObjectKey(key) {
666			writeError(w, http.StatusBadRequest, "invalid_request")
667			return
668		}
669		versionID, hasVersion, ok := parseVersionQuery(r.URL.RawQuery)
670		if !ok {
671			writeError(w, http.StatusBadRequest, "invalid_request")
672			return
673		}
674		s.mu.RLock()
675		b, bucketExists := s.buckets[bucketID]
676		var (
677			v             *objectVersion
678			notFoundCode  string
679			rejectInvalid bool
680		)
681		if bucketExists {
682			obj := b.objects[key]
683			switch {
684			case hasVersion && !b.versioningEnabled:
685				// Buckets without versioning keep their original behavior: any
686				// query parameter is an invalid request.
687				rejectInvalid = true
688			case hasVersion:
689				found, _ := b.findVersion(key, versionID)
690				if found == nil || found.isMarker {
691					notFoundCode = "object_version_not_found"
692				} else {
693					v = found
694				}
695			default:
696				// No versionId: serve the currently visible version (the latest
697				// data version unless it is hidden by a delete marker).
698				var cur *objectVersion
699				if obj != nil {
700					cur = obj.visible()
701				}
702				if cur == nil {
703					notFoundCode = "object_not_found"
704				} else {
705					v = cur
706				}
707			}
708		}
709		versioned := bucketExists && b.versioningEnabled
710		s.mu.RUnlock()
711		if !bucketExists {
712			writeError(w, http.StatusNotFound, "bucket_not_found")
713			return
714		}
715		if rejectInvalid {
716			writeError(w, http.StatusBadRequest, "invalid_request")
717			return
718		}
719		if notFoundCode != "" {
720			writeError(w, http.StatusNotFound, notFoundCode)
721			return
722		}
723		for name, value := range v.metadata {
724			w.Header().Set(metaPrefix+name, value)
725		}
726		w.Header().Set("ETag", v.etag)
727		if versioned {
728			w.Header().Set(versionHeader, v.versionID)
729		}
730		w.Header().Set("Content-Type", "application/octet-stream")
731		w.Header().Set("Content-Length", strconv.FormatInt(v.sizeBytes, 10))
732		w.WriteHeader(http.StatusOK)
733		if !headOnly {
734			_, _ = w.Write(v.content)
735		}
736	}
737	
738	func (s *store) deleteObject(w http.ResponseWriter, r *http.Request, bucketID, key string) {
739		if !validID(bucketID) || !validObjectKey(key) {
740			writeError(w, http.StatusBadRequest, "invalid_request")
741			return
742		}
743		versionID, hasVersion, ok := parseVersionQuery(r.URL.RawQuery)
744		if !ok {
745			writeError(w, http.StatusBadRequest, "invalid_request")
746			return
747		}
748		s.mu.Lock()
749		defer s.mu.Unlock()
750		b, exists := s.buckets[bucketID]
751		if !exists {
752			writeError(w, http.StatusNotFound, "bucket_not_found")
753			return
754		}
755		if !b.versioningEnabled {
756			s.deleteObjectUnversioned(w, b, key, r.URL.RawQuery)
757			return
758		}
759		resource := bucketPath + "/" + bucketID + "/objects/" + key
760		if !hasVersion {
761			obj := b.objects[key]
762			var latest *objectVersion
763			if obj != nil {
764				latest = obj.latest()
765			}
766			// Deleting with no versionId adds a delete marker; only when the
767			// latest version is already a marker is the request a successful
768			// no-op.
769			if latest != nil && latest.isMarker {
770				w.WriteHeader(http.StatusNoContent)
771				return
772			}
773			marker := &objectVersion{versionID: b.newVersionID(), isMarker: true}
774			if obj == nil {
775				obj = &object{key: key}
776				b.objects[key] = obj
777			}
778			obj.versions = append(obj.versions, marker)
779			// The marker charges no bytes; hidden data versions stay charged.
780			s.appendAudit(auditObjectMarker, resource, b.poolID, 0)
781			w.WriteHeader(http.StatusNoContent)
782			return
783		}
784		// A specific version is permanently removed; only a data version frees
785		// capacity. An unknown version (including a version of another key) is an
786		// error.
787		v, idx := b.findVersion(key, versionID)
788		if v == nil {
789			writeError(w, http.StatusNotFound, "object_version_not_found")
790			return
791		}
792		obj := b.objects[key]
793		obj.versions = append(obj.versions[:idx], obj.versions[idx+1:]...)
794		delta := int64(0)
795		if !v.isMarker {
796			delta = -v.sizeBytes
797			p := s.pools[b.poolID]
798			p.objectBytes -= v.sizeBytes
799			p.tenantUsed[b.tenant] -= v.sizeBytes
800		}
801		if len(obj.versions) == 0 {
802			delete(b.objects, key)
803		}
804		s.appendAudit(auditObjectVersionDel, resource, b.poolID, delta)
805		w.WriteHeader(http.StatusNoContent)
806	}
807	
808	// deleteObjectUnversioned preserves the original delete semantics for buckets
809	// without versioning: the single current version is removed, query strings
810	// are rejected, and deleting a missing object is a successful no-op. The
811	// caller holds the store lock.
812	func (s *store) deleteObjectUnversioned(w http.ResponseWriter, b *bucket, key, rawQuery string) {
813		if rawQuery != "" {
814			writeError(w, http.StatusBadRequest, "invalid_request")
815			return
816		}
817		if o, exists := b.objects[key]; exists && len(o.versions) > 0 {
818			v := o.versions[0]
819			s.pools[b.poolID].objectBytes -= v.sizeBytes
820			s.pools[b.poolID].tenantUsed[b.tenant] -= v.sizeBytes
821			delete(b.objects, key)
822			s.appendAudit(auditObjectDeleted, bucketPath+"/"+b.id+"/objects/"+key, b.poolID, -v.sizeBytes)
823		}
824		w.WriteHeader(http.StatusNoContent)
825	}
826	
827	// parsePrefixQuery accepts an empty query or exactly one "prefix=<value>"
828	// pair. Duplicated or unknown parameters yield ok=false.
829	func parsePrefixQuery(raw string) (string, bool) {
830		if raw == "" {
831			return "", true
832		}
833		var prefix string
834		found := false
835		for _, pair := range strings.Split(raw, "&") {
836			k, value, ok := strings.Cut(pair, "=")
837			if !ok {
838				return "", false
839			}
840			decodedKey, err := url.QueryUnescape(k)
841			if err != nil || decodedKey != "prefix" || found {
842				return "", false
843			}
844			decodedValue, err := url.QueryUnescape(value)
845			if err != nil {
846				return "", false
847			}
848			prefix, found = decodedValue, true
849		}
850		return prefix, found
851	}
852	
853	// parseVersionQuery accepts an empty query or exactly one non-empty
854	// "versionId=<value>" pair. Empty, duplicated, value-less or otherwise
855	// accompanied parameters yield ok=false.
856	func parseVersionQuery(raw string) (versionID string, present, ok bool) {
857		if raw == "" {
858			return "", false, true
859		}
860		for _, pair := range strings.Split(raw, "&") {
861			k, value, cutOK := strings.Cut(pair, "=")
862			if !cutOK {
863				return "", false, false
864			}
865			key, err := url.QueryUnescape(k)
866			if err != nil || key != "versionId" || present {
867				return "", false, false
868			}
869			decoded, err := url.QueryUnescape(value)
870			if err != nil || decoded == "" {
871				return "", false, false
872			}
873			versionID, present = decoded, true
874		}
875		return versionID, present, true
876	}
877	
878	func (s *store) listObjects(w http.ResponseWriter, r *http.Request, bucketID string) {
879		prefix, ok := parsePrefixQuery(r.URL.RawQuery)
880		if !ok || !validID(bucketID) {
881			writeError(w, http.StatusBadRequest, "invalid_request")
882			return
883		}
884		s.mu.RLock()
885		b, ok := s.buckets[bucketID]
886		var items []objectView
887		if ok {
888			keys := make([]string, 0, len(b.objects))
889			for k, obj := range b.objects {
890				// The ordinary listing shows only currently visible objects; a key
891				// whose latest version is a delete marker is omitted.
892				if obj.visible() != nil {
893					keys = append(keys, k)
894				}
895			}
896			sort.Strings(keys)
897			items = make([]objectView, 0, len(keys))
898			for _, k := range keys {
899				if strings.HasPrefix(k, prefix) {
900					items = append(items, b.objects[k].visible().objectView(k))
901				}
902			}
903		}
904		s.mu.RUnlock()
905		if !ok {
906			writeError(w, http.StatusNotFound, "bucket_not_found")
907			return
908		}
909		writeJSON(w, http.StatusOK, map[string]any{"items": items})
910	}
911	
912	// listObjectVersions handles GET /v1/buckets/{bucketId}/object-versions. It
913	// returns every matching data version and delete marker sorted by key
914	// ascending and, within one key, newest first.
915	func (s *store) listObjectVersions(w http.ResponseWriter, r *http.Request, bucketID string) {
916		prefix, ok := parsePrefixQuery(r.URL.RawQuery)
917		if !ok || !validID(bucketID) {
918			writeError(w, http.StatusBadRequest, "invalid_request")
919			return
920		}
921		s.mu.RLock()
922		b, exists := s.buckets[bucketID]
923		var items []objectVersionView
924		if exists {
925			keys := make([]string, 0, len(b.objects))
926			for k := range b.objects {
927				if strings.HasPrefix(k, prefix) {
928					keys = append(keys, k)
929				}
930			}
931			sort.Strings(keys)
932			items = make([]objectVersionView, 0)
933			for _, k := range keys {
934				obj := b.objects[k]
935				latest := len(obj.versions) - 1
936				for i := latest; i >= 0; i-- {
937					v := obj.versions[i]
938					row := objectVersionView{
939						Key:          k,
940						VersionID:    v.versionID,
941						IsLatest:     i == latest,
942						DeleteMarker: v.isMarker,
943						Metadata:     v.metadata,
944					}
945					if !v.isMarker {
946						row.SizeBytes = v.sizeBytes
947						row.Etag = v.etag
948						if row.Metadata == nil {
949							row.Metadata = map[string]string{}
950						}
951					} else {
952						row.Metadata = map[string]string{}
953					}
954					items = append(items, row)
955				}
956			}
957		}
958		s.mu.RUnlock()
959		if !exists {
960			writeError(w, http.StatusNotFound, "bucket_not_found")
961			return
962		}
963		writeJSON(w, http.StatusOK, map[string]any{"items": items})
964	}
